{
 "cases": [
  {
   "name": "普通请求，qwen-mini 模型，无图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ]
   },
   "raw_body": null,
   "expect_status": 200,
   "expect_code": null
  },
  {
   "name": "流式请求，qwen-mini 模型，无图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": null,
   "raw_body": null,
   "expect_status": 200,
   "expect_code": null
  },
  {
   "name": "temperature 为 0，qwen-mini 模型，无图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 0
   },
   "raw_body": null,
   "expect_status": 200,
   "expect_code": null
  },
  {
   "name": "temperature 超过上限，qwen-mini 模型，无图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "max_tokens 超过上限，qwen-mini 模型，无图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "max_tokens": 4097
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "使用 embedding 模型，qwen-mini 模型，无图片",
   "method": "POST",
   "path": "/v1/embeddings",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "input": "你好"
   },
   "raw_body": null,
   "expect_status": 200,
   "expect_code": null
  },
  {
   "name": "使用 qwen-vl 模型，qwen-mini 模型，有图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-vl",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     },
     {
      "role": "assistant",
      "content": "这是图片",
      "image_url": "https://example.com/image.png"
     }
    ]
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "image_not_supported"
  }
 ]}
